/**
 * Connect RPC method idempotency from the site's code (decision 0050). Code generated by
 * protobuf-es embeds each `.proto` file as a base64 `FileDescriptorProto` (v2) or as service
 * objects `{typeName: "pkg.Service", methods: {getX: {name: "GetX", …, idempotency: X.NoSideEffects}}}`
 * (v1). A method whose `idempotency_level` is `NO_SIDE_EFFECTS` promises not to change data, the
 * same promise Connect makes when it sends the call as a GET.
 */

export type Idempotency = 'no-side-effects' | 'idempotent'

/** Larger embedded descriptors are not read: no `.proto` file is this big. */
const MAX_DESCRIPTOR_BYTES = 1024 * 1024
/** Base64 text of a descriptor: field 1 (the file name) first, so it starts `Cg`…`Cj`. */
const DESCRIPTOR_LITERAL = /["'`](C[g-j][\w+/-]{40,}={0,2})["'`]/g
/** v1 service objects; the methods follow within a few kilobytes. */
const V1_SERVICE = /typeName:\s*["'`]((?:[A-Za-z_]\w*\.)+[A-Za-z_]\w*)["'`]\s*,\s*methods:\s*\{/g
const V1_METHOD = /\{\s*name:\s*["'`]([A-Za-z_]\w*)["'`][^{}]*?idempotency:\s*[\w$]+\.(NoSideEffects|Idempotent)\b[^{}]*\}/g
const V1_WINDOW = 50_000

class Invalid extends Error {}

class Reader {
  offset = 0
  constructor(private readonly bytes: Uint8Array) {}

  get done(): boolean {
    return this.offset >= this.bytes.length
  }

  varint(): number {
    let result = 0
    let shift = 0
    for (;;) {
      const byte = this.bytes[this.offset++]
      if (byte === undefined || shift > 49)
        throw new Invalid()
      result += (byte & 0x7F) * 2 ** shift
      if ((byte & 0x80) === 0)
        return result
      shift += 7
    }
  }

  take(length: number): Uint8Array {
    if (length < 0 || this.offset + length > this.bytes.length)
      throw new Invalid()
    const slice = this.bytes.subarray(this.offset, this.offset + length)
    this.offset += length
    return slice
  }

  /** Every field as `[number, value]`: a number for varints, bytes for length-delimited ones. */
  fields(): Array<[number, number | Uint8Array]> {
    const fields: Array<[number, number | Uint8Array]> = []
    while (!this.done) {
      const key = this.varint()
      const field = Math.floor(key / 8)
      const wire = key % 8
      if (field === 0)
        throw new Invalid()
      if (wire === 0) {
        fields.push([
          field,
          this.varint(),
        ])
      }
      else if (wire === 2) {
        fields.push([
          field,
          this.take(this.varint()),
        ])
      }
      else if (wire === 1) {
        this.take(8)
      }
      else if (wire === 5) {
        this.take(4)
      }
      else {
        throw new Invalid()
      }
    }
    return fields
  }
}

const utf8 = new TextDecoder('utf-8', { fatal: true })

function text(value: number | Uint8Array): string {
  if (typeof value === 'number')
    throw new Invalid()
  return utf8.decode(value)
}

function bytes(value: number | Uint8Array): Uint8Array {
  if (typeof value === 'number')
    throw new Invalid()
  return value
}

const LEVELS: Readonly<Record<number, Idempotency>> = { 1: 'no-side-effects', 2: 'idempotent' }

/** `MethodOptions.idempotency_level` (field 34), if set. */
function methodLevel(options: Uint8Array): Idempotency | null {
  for (const [field, value] of new Reader(options).fields()) {
    if (field === 34 && typeof value === 'number')
      return LEVELS[value] ?? null
  }
  return null
}

/** The methods of one `ServiceDescriptorProto` that state an idempotency level. */
function addServiceMethods(prefix: string, data: Uint8Array, result: Map<string, Idempotency>): void {
  const service = new Reader(data).fields()
  const serviceName = service.find(([number]) => number === 1)
  if (serviceName === undefined)
    return
  for (const [number, method] of service) {
    if (number !== 2)
      continue
    const parts = new Reader(bytes(method)).fields()
    const methodName = parts.find(([part]) => part === 1)
    const options = parts.find(([part]) => part === 4)
    const level = options === undefined
      ? null
      : methodLevel(bytes(options[1]))
    if (methodName !== undefined && level !== null)
      result.set(`${prefix}${text(serviceName[1])}/${text(methodName[1])}`, level)
  }
}

/**
 * The idempotency of every method of one serialized `FileDescriptorProto`, keyed
 * `package.Service/Method`; null when the bytes are not a descriptor of a `.proto` file.
 */
export function descriptorIdempotency(data: Uint8Array): Map<string, Idempotency> | null {
  try {
    const file = new Reader(data).fields()
    const name = file.find(([field]) => field === 1)
    if (name === undefined || !text(name[1]).endsWith('.proto'))
      return null
    const pkg = file.find(([field]) => field === 2)
    const prefix = pkg === undefined
      ? ''
      : `${text(pkg[1])}.`
    const result = new Map<string, Idempotency>()
    for (const [field, value] of file) {
      if (field === 6)
        addServiceMethods(prefix, bytes(value), result)
    }
    return result
  }
  catch (error) {
    if (error instanceof Invalid || error instanceof TypeError)
      return null
    throw error
  }
}

function base64Bytes(literal: string): Uint8Array | null {
  const standard = literal.replace(/-/g, '+').replace(/_/g, '/')
  const padded = standard.padEnd(Math.ceil(standard.length / 4) * 4, '=')
  try {
    return Uint8Array.from(atob(padded), char => char.charCodeAt(0))
  }
  catch {
    return null
  }
}

/** Methods marked `NO_SIDE_EFFECTS` or `IDEMPOTENT` in one code file, both generations. */
export function connectIdempotencyInText(code: string): Map<string, Idempotency> {
  const result = new Map<string, Idempotency>()
  for (const match of code.matchAll(DESCRIPTOR_LITERAL)) {
    const literal = match[1] ?? ''
    if (literal.length * 0.75 > MAX_DESCRIPTOR_BYTES)
      continue
    const data = base64Bytes(literal)
    const methods = data === null
      ? null
      : descriptorIdempotency(data)
    for (const [method, level] of methods ?? [])
      result.set(method, level)
  }
  for (const service of code.matchAll(V1_SERVICE)) {
    const start = (service.index ?? 0) + service[0].length
    const next = code.indexOf('typeName:', start)
    const window = code.slice(start, Math.min(start + V1_WINDOW, next === -1
      ? code.length
      : next))
    for (const method of window.matchAll(V1_METHOD)) {
      result.set(`${service[1] ?? ''}/${method[1] ?? ''}`, method[2] === 'NoSideEffects'
        ? 'no-side-effects'
        : 'idempotent')
    }
  }
  return result
}
